import { scryptSync, randomBytes, timingSafeEqual } from 'crypto'

// scrypt with per-user salt — matches the existing farmer login pattern
// Format on disk: "salt_hex:hash_hex"
export function hashPassword(password: string): string {
  const salt = randomBytes(16).toString('hex')
  const hash = scryptSync(password, salt, 64).toString('hex')
  return `${salt}:${hash}`
}

export function verifyPassword(password: string, stored: string): boolean {
  try {
    const [salt, hash] = stored.split(':')
    if (!salt || !hash) return false
    const hashBuffer = Buffer.from(hash, 'hex')
    const derived = scryptSync(password, salt, 64)
    if (hashBuffer.length !== derived.length) return false
    return timingSafeEqual(hashBuffer, derived)
  } catch {
    return false
  }
}

import { createClient } from '@supabase/supabase-js'
import { NextRequest, NextResponse } from 'next/server'
import { hashPassword, verifyPassword } from '@/lib/password'
import { getFarmerSessionFromRequest } from '@/lib/farmer-session'
import { rateLimit } from '@/lib/rate-limit'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

export async function POST(req: NextRequest) {
  // The previous version trusted a body-supplied farmerId — that let anyone
  // who guessed/scraped a farmer UUID change their password. Now we read the
  // farmerId from the auth cookie only.
  const session = getFarmerSessionFromRequest(req)
  if (!session) {
    return NextResponse.json({ error: 'Please log in first.' }, { status: 401 })
  }

  const ip = req.headers.get('x-forwarded-for')?.split(',')[0]?.trim() || 'unknown'
  if (
    !rateLimit(`reset-pw:farmer:${session.farmerId}`, 5, 60 * 60 * 1000) ||
    !rateLimit(`reset-pw:ip:${ip}`, 15, 60 * 60 * 1000)
  ) {
    return NextResponse.json({ error: 'Too many attempts. Try again later.' }, { status: 429 })
  }

  const body = await req.json().catch(() => ({}))
  const currentPassword: string = String((body as { currentPassword?: unknown }).currentPassword ?? '')
  const newPassword: string = String((body as { newPassword?: unknown }).newPassword ?? '').trim()

  if (!currentPassword) {
    return NextResponse.json({ error: 'Current password is required.' }, { status: 400 })
  }
  if (newPassword.length < 6) {
    return NextResponse.json({ error: 'Password must be at least 6 characters.' }, { status: 400 })
  }
  if (newPassword.length > 128) {
    return NextResponse.json({ error: 'Password is too long.' }, { status: 400 })
  }

  const supabase = createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
  )

  // Verify the current password against the stored hash before allowing
  // an update. Without this, anyone with a live session could change the
  // password without knowing the existing one.
  const { data: farmer } = await supabase
    .from('farmers')
    .select('password_hash')
    .eq('id', session.farmerId)
    .maybeSingle()

  if (!farmer?.password_hash || !verifyPassword(currentPassword, farmer.password_hash)) {
    return NextResponse.json({ error: 'Current password is incorrect' }, { status: 400 })
  }

  const { error } = await supabase
    .from('farmers')
    .update({ password_hash: hashPassword(newPassword) })
    .eq('id', session.farmerId)

  if (error) return NextResponse.json({ error: error.message }, { status: 500 })
  return NextResponse.json({ ok: true })
}

